#include <chrono>
#include <condition_variable>
#include <cstdint>
#include <format>
#include <iostream>
#include <mutex>
#include <string>
#include <thread>
#include <utility>
#include <vector>

struct Map {
  std::string name;
  std::int64_t cells = 0;
};

class MapHandoff {
 public:
  // The state changes under the lock; the notification goes out after the lock is released.
  void publish(Map map) {
    {
      const std::lock_guard<std::mutex> lock(mutex_);
      map_ = std::move(map);
      loaded_ = true;
    }
    loaded_cv_.notify_all();
  }

  [[nodiscard]] Map wait_for_map() {
    std::unique_lock<std::mutex> lock(mutex_);
    loaded_cv_.wait(lock, [this] { return loaded_; });
    return map_;
  }

 private:
  std::mutex mutex_;
  std::condition_variable loaded_cv_;
  bool loaded_ = false;
  Map map_;
};

int main() {
  MapHandoff handoff;
  std::vector<std::string> seen(2);
  {
    std::vector<std::jthread> planners;
    planners.reserve(seen.size());
    for (std::ptrdiff_t i = 0; i < std::ssize(seen); ++i) {
      planners.emplace_back([&handoff, slot = &seen[i]] {
        const Map map = handoff.wait_for_map();
        *slot = std::format("{} with {} cells", map.name, map.cells);
      });
    }
    std::this_thread::sleep_for(std::chrono::milliseconds(20));
    handoff.publish({.name = "warehouse", .cells = 4'000'000});
  }
  for (std::ptrdiff_t i = 0; i < std::ssize(seen); ++i) {
    std::cout << std::format("planner {} got {}\n", i, seen[i]);
  }
}

#include <chrono>
#include <condition_variable>
#include <cstdint>
#include <format>
#include <iostream>
#include <mutex>
#include <optional>
#include <thread>

constexpr std::int64_t kBeats = 3;
constexpr auto kGap = std::chrono::milliseconds(100);

// One beat at a time: the publisher waits for the monitor to take the last one.
class Heartbeat {
 public:
  void beat(std::int64_t seq) {
    {
      std::unique_lock<std::mutex> lock(mutex_);
      taken_.wait(lock, [this] { return !pending_.has_value(); });
      pending_ = seq;
    }
    arrived_.notify_one();
  }

  // The new sequence number, or no value when nothing arrived within the limit.
  [[nodiscard]] std::optional<std::int64_t> take(std::chrono::milliseconds limit) {
    std::optional<std::int64_t> seq;
    {
      std::unique_lock<std::mutex> lock(mutex_);
      if (!arrived_.wait_for(lock, limit, [this] { return pending_.has_value(); })) return std::nullopt;
      seq = pending_;
      pending_.reset();
    }
    taken_.notify_one();
    return seq;
  }

 private:
  std::mutex mutex_;
  std::condition_variable arrived_;  // waited on by the monitor: a beat is pending
  std::condition_variable taken_;    // waited on by the publisher: the slot is free
  std::optional<std::int64_t> pending_;
};

int main() {
  Heartbeat heartbeat;
  std::int64_t gaps = 0;
  {
    std::jthread monitor([&heartbeat, &gaps] {
      for (std::int64_t seen = 0; seen < kBeats + 1; ++seen) {
        const std::optional<std::int64_t> seq = heartbeat.take(kGap);
        if (seq.has_value()) {
          std::cout << std::format("monitor got beat {}\n", seq.value());
        } else {
          ++gaps;
          std::cout << std::format("monitor saw no beat for {} ms\n", kGap.count());
        }
      }
    });
    for (std::int64_t seq = 1; seq <= kBeats; ++seq) heartbeat.beat(seq);
  }
  std::cout << std::format("publisher sent {} beats, monitor reported {} gap\n", kBeats, gaps);
}

#include <chrono>
#include <condition_variable>
#include <format>
#include <iostream>
#include <mutex>

class MapHandoff {
 public:
  void publish() {
    {
      const std::lock_guard<std::mutex> lock(mutex_);
      loaded_ = true;
    }
    loaded_cv_.notify_all();
  }

  // Wrong: wait() carries no memory. A notification sent before this call is gone for good.
  void wait_without_predicate(std::chrono::milliseconds limit) {
    std::unique_lock<std::mutex> lock(mutex_);
    const auto deadline = std::chrono::steady_clock::now() + limit;
    while (std::chrono::steady_clock::now() < deadline) loaded_cv_.wait_until(lock, deadline);
  }

  // Right: the predicate is the memory. It is checked before the first wait.
  [[nodiscard]] bool wait_with_predicate(std::chrono::milliseconds limit) {
    std::unique_lock<std::mutex> lock(mutex_);
    return loaded_cv_.wait_for(lock, limit, [this] { return loaded_; });
  }

  [[nodiscard]] bool loaded() const {
    const std::lock_guard<std::mutex> lock(mutex_);
    return loaded_;
  }

 private:
  mutable std::mutex mutex_;
  std::condition_variable loaded_cv_;
  bool loaded_ = false;
};

int main() {
  constexpr auto kLimit = std::chrono::milliseconds(200);
  MapHandoff handoff;
  handoff.publish();  // the map arrives before anybody waits
  std::cout << std::format("published first: loaded {}\n", handoff.loaded());

  const auto start = std::chrono::steady_clock::now();
  handoff.wait_without_predicate(kLimit);
  const bool waited_the_lot = std::chrono::steady_clock::now() - start >= kLimit;
  std::cout << std::format("no predicate: waited the full {} ms: {}; loaded {}\n", kLimit.count(), waited_the_lot,
                           handoff.loaded());
  std::cout << std::format("with a predicate: returned {}\n", handoff.wait_with_predicate(kLimit));
}

void publish(Map map) {
  map_ = std::move(map);  // no lock
  loaded_ = true;
  loaded_cv_.notify_all();
}

#include <chrono>
#include <condition_variable>
#include <cstdint>
#include <format>
#include <iostream>
#include <mutex>
#include <string>
#include <thread>
#include <vector>

// One-shot: set() once, and every wait after that returns at once.
class Event {
 public:
  void set() {
    {
      const std::lock_guard<std::mutex> lock(mutex_);
      if (set_) return;
      set_ = true;
    }
    cv_.notify_all();  // every waiter is waiting for the same thing, so wake them all
  }

  void wait() const {
    std::unique_lock<std::mutex> lock(mutex_);
    cv_.wait(lock, [this] { return set_; });
  }

  [[nodiscard]] bool wait_for(std::chrono::milliseconds limit) const {
    std::unique_lock<std::mutex> lock(mutex_);
    return cv_.wait_for(lock, limit, [this] { return set_; });
  }

  [[nodiscard]] bool is_set() const {
    const std::lock_guard<std::mutex> lock(mutex_);
    return set_;
  }

 private:
  mutable std::mutex mutex_;
  mutable std::condition_variable cv_;
  bool set_ = false;
};

// Counts down to zero once, and then stays there.
class Countdown {
 public:
  explicit Countdown(std::int64_t count) : left_(count) {}

  void count_down() {
    bool reached_zero = false;
    {
      const std::lock_guard<std::mutex> lock(mutex_);
      if (left_ > 0) {
        --left_;
        reached_zero = left_ == 0;
      }
    }
    if (reached_zero) cv_.notify_all();
  }

  void wait() const {
    std::unique_lock<std::mutex> lock(mutex_);
    cv_.wait(lock, [this] { return left_ == 0; });
  }

  [[nodiscard]] std::int64_t left() const {
    const std::lock_guard<std::mutex> lock(mutex_);
    return left_;
  }

 private:
  mutable std::mutex mutex_;
  mutable std::condition_variable cv_;
  std::int64_t left_ = 0;
};

int main() {
  constexpr std::ptrdiff_t kPlanners = 3;
  constexpr std::int64_t kWorkers = 4;

  Event start_driving;
  Countdown calibrated(kWorkers);
  std::vector<std::string> notes(kPlanners);

  std::cout << std::format("before anything: event set {}, countdown left {}\n", start_driving.is_set(),
                           calibrated.left());
  std::cout << std::format("wait_for on an unset event returns {}\n",
                           start_driving.wait_for(std::chrono::milliseconds(50)));

  {
    std::vector<std::jthread> threads;
    threads.reserve(kPlanners + kWorkers);
    for (std::ptrdiff_t i = 0; i < kPlanners; ++i) {
      threads.emplace_back([&start_driving, slot = &notes[i], i] {
        start_driving.wait();
        *slot = std::format("planner {} started", i);
      });
    }
    for (std::int64_t i = 0; i < kWorkers; ++i) {
      threads.emplace_back([&calibrated] { calibrated.count_down(); });
    }
    calibrated.wait();  // every worker has finished calibrating
    std::cout << std::format("all {} workers calibrated, countdown left {}\n", kWorkers, calibrated.left());
    start_driving.set();
  }

  for (const std::string& note : notes) std::cout << note << "\n";
  std::cout << std::format("after set: event set {}, a later wait_for returns {}\n", start_driving.is_set(),
                           start_driving.wait_for(std::chrono::milliseconds(50)));
}
